import math
X=0.0;Y=0.0;TH=0.0
MAP={}
TGT=None
phase='rev'
fwd_d=0.0
LOOK=[150,64,-64,-150,-64,64]
li=0;hold=0.0
last_t=None
last_prune=0.0
last_print=-10.0
woke=False

def tow(vx,vy):
    c=math.cos(TH);s=math.sin(TH)
    return (X+vx*c-vy*s, Y+vx*s+vy*c)

def tov(wx,wy):
    dx=wx-X;dy=wy-Y;c=math.cos(TH);s=math.sin(TH)
    return (dx*c+dy*s, -dx*s+dy*c)

def clamp(v,a,b):
    return a if v<a else (b if v>b else v)

def freescan(pts,w):
    bs=list(range(-60,61,4));ds=[]
    for bd in bs:
        b=math.radians(bd);cb=math.cos(b);sb=math.sin(b);d=10.0
        for (al,la) in pts:
            a2=al*cb+la*sb
            if a2>0.3 and a2<d:
                l2=-al*sb+la*cb
                if abs(l2)<w: d=a2
        ds.append(d)
    return bs,ds

def control(obs):
    global X,Y,TH,li,hold,last_t,TGT,phase,fwd_d,last_prune,last_print,woke
    t=obs['t'];dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    if last_t is not None:
        h=t-last_t
        if 0<h<1:
            X+=v*math.cos(TH)*h;Y+=v*math.sin(TH)*h;TH+=v*math.tan(st)/2.5*h
            if phase=='fwd': fwd_d+=abs(v)*h
    last_t=t
    # head
    hd=obs.get('head') or {}
    tgtl=LOOK[li]
    if hd.get('settled') and abs(hd.get('gaze_deg',0)-tgtl)<3:
        hold+=dt
        if hold>=0.3:
            li=(li+1)%len(LOOK);hold=0.0;tgtl=LOOK[li]
    try:
        views=obs.get('views') or {}
        for name,vw in views.items():
            if not vw: continue
            o=vw.get('origin',[0,0])
            for p in vw.get('walls',[]) or []:
                b,d=p[0],p[1]
                if d>14: continue
                px=o[0]+d*math.cos(math.radians(b));py=o[1]+d*math.sin(math.radians(b))
                wx,wy=tow(px,py)
                MAP[(round(wx*4),round(wy*4))]=(wx,wy,t)
        if t-last_prune>1.0:
            last_prune=t
            for k in [k for k,vv in MAP.items() if t-vv[2]>25]: del MAP[k]
        tg=obs.get('target') or {}
        rig=obs['rig']
        if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None and tg['dist_m']<15:
            b=math.radians(tg['bearing_deg']);e=rig['eye']
            wx,wy=tow(e[0]+tg['dist_m']*math.cos(b),e[1]+tg['dist_m']*math.sin(b))
            if TGT is None: TGT=[wx,wy]
            else:
                k=0.3 if tg['dist_m']<6 else 0.15
                TGT=[(1-k)*TGT[0]+k*wx,(1-k)*TGT[1]+k*wy]
        phi=obs['hitch_deg']
        status=obs.get('status')
        if status=='JACKKNIFED' or abs(phi)>50:
            if phase!='fwd': phase='fwd';fwd_d=0.0
        if phase=='fwd':
            if abs(phi)<8 or fwd_d>4.0:
                phase='rev'
            else:
                return (clamp(-1.5*phi,-35,35),0.8,tgtl)
        hx,hy=rig['hitch'];rx,ry=rig['trailer_rear']
        ux,uy=rx-hx,ry-hy;n=math.hypot(ux,uy) or 1.0;ux/=n;uy/=n
        pts=[]
        for (wx,wy,tt) in MAP.values():
            vx,vy=tov(wx,wy);qx=vx-rx;qy=vy-ry
            if qx*qx+qy*qy>144: continue
            al=qx*ux+qy*uy
            if al<-1.0: continue
            pts.append((al,ux*qy-uy*qx))
        bs,ds=freescan(pts,1.6)
        if max(ds)<3.0:
            bs,ds=freescan(pts,1.3)
        dmax=max(ds)
        good=[d>=dmax-0.6 for d in ds]
        best=None;i=0
        while i<len(bs):
            if good[i]:
                j=i
                while j+1<len(bs) and good[j+1]: j+=1
                c=(bs[i]+bs[j])/2.0;L=j-i
                key=(L,-abs(c))
                if best is None or key>best[0]: best=(key,c)
                i=j+1
            else: i+=1
        beta=best[1] if best else 0.0
        Ld=max(2.5,min(6.0,dmax))
        src='free'
        if TGT is not None:
            vx,vy=tov(TGT[0],TGT[1]);qx=vx-rx;qy=vy-ry
            al=qx*ux+qy*uy;la=ux*qy-uy*qx;dt_=math.hypot(qx,qy)
            if al>1.0 and dt_<12:
                beta=math.degrees(math.atan2(la,al));Ld=max(2.5,dt_);src='tgt'
        kap=2*math.sin(math.radians(beta))/Ld
        phiref=-math.degrees(math.asin(clamp(kap*3.6,-0.6,0.6)))
        pr=math.radians(phi)
        deq=math.degrees(math.atan(2.5*math.sin(pr)/(3.6+1.3*math.cos(pr))))
        steer=clamp(deq+2.0*(phi-phiref),-45,45)
        sp=-max(0.4,min(1.0,0.25*dmax))
        if abs(phi-phiref)>15: sp=max(sp,-0.5)
        if dmax<0.5 and src=='free':
            sp=0.0
            if not woke:
                woke=True;wake('blocked: free distance %.2f'%dmax)
        if t-last_print>3:
            last_print=t
            print('t%.0f phi%.0f ref%.0f st%.0f b%.0f d%.1f %s n%d' % (t,phi,phiref,steer,beta,dmax,src,len(pts)))
        return (steer,sp,tgtl)
    except Exception as ex:
        print('err',ex)
        return (obs.get('steer_deg',0),0.0,tgtl)

