import math
X=0.0;Y=0.0;H=-0.40
occ=set()
C=0.3
PSI_D=2.07
lastprint=-10.0
cdir=0.0
freeL=8.0
phid_f=-39.0
hist=[]
stopped=False
woke_t=-100.0
L1=3.9;L2=10.2;A=0.35;HW=1.275

def cell(x,y):
    return (int(math.floor(x/C)),int(math.floor(y/C)))

def tw(px,py):
    c=math.cos(H);s=math.sin(H)
    return (X+px*c-py*s, Y+px*s+py*c)

def add_view(v):
    try:
        ox,oy=v['origin']
    except Exception:
        return
    pts=[]
    for w in v.get('walls',[]) or []:
        b,d=w[0],w[1]
        if d>15: continue
        r=math.radians(b)
        pts.append(tw(ox+d*math.cos(r),oy+d*math.sin(r)))
    for p in pts:
        occ.add(cell(p[0],p[1]))
    for i in range(len(pts)-1):
        a=pts[i];b=pts[i+1]
        dd=math.hypot(b[0]-a[0],b[1]-a[1])
        if 0<dd<1.5:
            n=int(dd/0.15)+1
            for j in range(1,n):
                f=j/float(n)
                occ.add(cell(a[0]+f*(b[0]-a[0]),a[1]+f*(b[1]-a[1])))

def clear(px,py):
    w=tw(px,py);cx,cy=cell(w[0],w[1]);best=9.0
    for i in range(-5,6):
        for j in range(-5,6):
            if (cx+i,cy+j) in occ:
                d=math.hypot((cx+i+0.5)*C-w[0],(cy+j+0.5)*C-w[1])
                if d<best: best=d
    return best

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def control(obs):
    global X,Y,H,lastprint,cdir,freeL,phid_f,hist,stopped,woke_t
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0.0)
    mo=obs.get('motion',{}) or {}
    v=mo.get('v_mps',0.0) or 0.0
    st=obs.get('steer_deg',0.0) or 0.0
    X+=v*math.cos(H)*dt;Y+=v*math.sin(H)*dt
    H+=v*math.tan(math.radians(st))/L1*dt
    views=obs.get('views',{}) or {}
    for name,vw in views.items():
        if isinstance(vw,dict): add_view(vw)
    phi=obs.get('hitch_deg',0.0) or 0.0
    status=obs.get('status','')
    rem=(obs.get('progress',{}) or {}).get('remaining',50.0)
    if rem is None: rem=50.0
    m=t%6.4
    if m<2.3 or (3.2<=m<5.5): look=-41
    elif m<3.2: look=53
    else: look=-72
    rig=obs.get('rig',{}) or {}
    hi=rig.get('hitch',[0.35,0.0])
    tr=rig.get('trailer_rear',[-11.75,0.0])
    vf=rig.get('vehicle_front',None)
    try:
        fx=float(vf[0]) if isinstance(vf,(list,tuple)) else float(vf)
    except Exception:
        fx=4.6
    rx=fx-6.2
    th=math.radians(-phi);ux=math.cos(th);uy=math.sin(th)
    tfl=(hi[0]+1.4*ux-HW*uy,hi[1]+1.4*uy+HW*ux)
    tfr=(hi[0]+1.4*ux+HW*uy,hi[1]+1.4*uy-HW*ux)
    trl=(tr[0]-HW*uy,tr[1]+HW*ux)
    trr=(tr[0]+HW*uy,tr[1]-HW*ux)
    dfl_t=clear(*tfl);drl=clear(*trl);dfr_t=clear(*tfr);drr=clear(*trr)
    vrl=min(clear(rx,HW),clear(rx+1.0,HW));vrr=clear(rx,-HW)
    dfl=clear(fx,HW);dfr=clear(fx,-HW)
    vals=[dfl_t,drl,dfr_t,drr,vrl,vrr,dfl,dfr]
    hist.append(vals)
    if len(hist)>10: hist.pop(0)
    psi_t=H-math.radians(phi)
    cam=views.get('camera') if isinstance(views,dict) else None
    if isinstance(cam,dict):
        rd=180.0-phi
        pts=[(wrap(w[0]-rd),w[1]) for w in (cam.get('walls') or [])]
        best=None;bc=cdir;bf=freeL
        for i in range(29):
            c=-70+5*i
            f=15.0
            for (rb,d) in pts:
                a=math.radians(rb-c)
                al=d*math.cos(a);la=d*math.sin(a)
                if al>0 and abs(la)<1.7 and al<f: f=al
            sc=f-0.04*abs(c)-0.02*abs(c-cdir)
            if best is None or sc>best: best=sc;bc=c;bf=f
        cdir=0.5*cdir+0.5*bc;freeL=bf
