    if drr<0.9: phid=max(phid,min(45,phi+8))
    if dfl_t<0.6 and phid<phi: phid=phi+5
    if dfr_t<0.6 and phid>phi: phid=phi-5
    phid_f=phid_f+0.5*(phid-phid_f)
    pr=math.radians(phid_f)
    ff=math.degrees(math.atan(L1*math.sin(pr)/(L2+A*math.cos(pr))))
    bias=0.0
    if dfl<0.8: bias+=25*(0.8-dfl)/0.8
    if dfr<0.8: bias-=25*(0.8-dfr)/0.8
    steer=ff+2.0*(phi-phid_f)+bias
    if vrl<1.3 and phi>-55: steer=min(steer,-35.0*(1.3-vrl)/0.9)
    if vrr<1.0 and phi<55: steer=max(steer,25.0*(1.0-vrr))
    if phi<-55: steer=max(steer,20.0)
    if phi>55: steer=min(steer,-20.0)
